def k_window_consecutive_power(nums,k):
    run=1;answer=[]
    for index,number in enumerate(nums):
        if index and number==nums[index-1]+1:run+=1
        else:run=1
        if index>=k-1:answer.append(number if run>=k else -1)
    return answer

